<template><view class="page"><view class="top"><text class="back" @tap="back">‹</text><text class="title">到店服务进度</text><text class="blank"></text></view><scroll-view scroll-y class="scroll"><view class="pad"><view v-for="r in rows" :key="r.request_id" class="card"><view class="row"><text class="kind">{{labels[r.request_type]||r.request_type}}</text><text :class="['status',r.status==='已完成'&&'done']">{{r.status}}</text></view><text class="meta">{{r.store_name||'奇德芬芳'}}<text v-if="r.room_no"> · 房间 {{r.room_no}}</text></text><text v-if="r.content" class="content">{{r.content}}</text><text class="time">提交于 {{fmt(r.created_at)}}</text></view><view v-if="!rows.length&&!loading" class="empty">暂无到店服务记录</view></view></scroll-view></view></template>
<script>import{loadServiceRequests}from'@/common/remote.js';export default{data(){return{rows:[],loading:false,labels:{arrival_checkin:'到店签到',concierge:'呼叫管家',housekeeping:'客房清洁',meal_request:'膳食需求',baby_care:'宝宝护理',rehab_booking:'产康预约'}}},onShow(){this.load()},onPullDownRefresh(){this.load().finally(()=>uni.stopPullDownRefresh())},methods:{back(){uni.navigateBack()},fmt(v){return String(v||'').replace('T',' ').slice(0,16)},async load(){this.loading=true;try{this.rows=await loadServiceRequests()}catch(e){uni.showToast({title:e.message||'加载失败',icon:'none'})}finally{this.loading=false}}}}</script>
<style lang="scss" scoped>.page{height:100vh;background:$ivory;display:flex;flex-direction:column}.top{padding:calc(env(safe-area-inset-top) + 20rpx) 34rpx 12rpx;display:flex;justify-content:space-between;align-items:center}.back,.blank{width:60rpx}.back{font-size:52rpx;color:$gold-deep}.title{font-family:$font-cn-serif;font-size:31rpx}.scroll{flex:1}.pad{padding:24rpx 34rpx 80rpx}.card{background:#fff;border:1rpx solid $hair;border-radius:28rpx;padding:28rpx;margin-bottom:18rpx}.row{display:flex;justify-content:space-between}.kind{font-family:$font-cn-serif;font-size:29rpx}.status{font-size:21rpx;color:$gold-deep;background:#F5E7CA;padding:6rpx 14rpx;border-radius:30rpx}.status.done{color:#4A8060;background:#E3F2E8}.meta,.content,.time{display:block}.meta{color:$ink-2;font-size:22rpx;margin-top:8rpx}.content{font-size:24rpx;margin-top:16rpx}.time{color:$ink-3;font-size:20rpx;margin-top:16rpx}.empty{text-align:center;color:$ink-3;padding:160rpx 20rpx}</style>
